The design synchronizes `sclk`, `mosi`, and `cs_n` into the `clk` domain with two-flop synchronizers. A third register on `sclk` provides the previous value for rising-edge detection.

On each detected rising edge while `cs_n` is low, `mosi` is shifted into a register and the bit count is incremented. When the count reaches 7, the completed byte is `{shift[6:0], mosi_s}`. It is written to `data` and `valid` is pulsed for one cycle. While `cs_n` is high, the bit count is cleared.

`mosi` is sampled at the same synchronized instant as the `sclk` edge. Both pass through the same two-stage synchronizer, so they stay aligned, and `mosi` is stable around the `sclk` rising edge in mode 0.

A state machine is not needed, so I use a simple counter. `valid` defaults to 0 each cycle and is set only on the byte-completion edge.

```systemverilog
module spi_slave_rx (
    input  logic       clk,    // system clock
    input  logic       rst_n,  // active-low synchronous reset
    input  logic       sclk,   // SPI clock from master (asynchronous to clk)
    input  logic       mosi,   // master-out slave-in data
    input  logic       cs_n,   // active-low chip select
    output logic [7:0] data,   // last complete byte received
    output logic       valid   // one-clk-cycle pulse when data is updated
);

    logic [1:0] sclk_sync;
    logic [1:0] mosi_sync;
    logic [1:0] cs_sync;
    logic       sclk_prev;
    logic [6:0] shift;
    logic [2:0] bit_cnt;

    logic sclk_s, mosi_s, cs_s;
    logic sclk_rise;

    assign sclk_s = sclk_sync[1];
    assign mosi_s = mosi_sync[1];
    assign cs_s   = cs_sync[1];
    assign sclk_rise = sclk_s & ~sclk_prev;

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            sclk_sync <= 2'b00;
            mosi_sync <= 2'b00;
            cs_sync   <= 2'b11;
            sclk_prev <= 1'b0;
            shift     <= 7'd0;
            bit_cnt   <= 3'd0;
            data      <= 8'd0;
            valid     <= 1'b0;
        end else begin
            sclk_sync <= {sclk_sync[0], sclk};
            mosi_sync <= {mosi_sync[0], mosi};
            cs_sync   <= {cs_sync[0], cs_n};
            sclk_prev <= sclk_s;
            valid     <= 1'b0;

            if (cs_s) begin
                bit_cnt <= 3'd0;
            end else if (sclk_rise) begin
                if (bit_cnt == 3'd7) begin
                    data    <= {shift, mosi_s};
                    valid   <= 1'b1;
                    bit_cnt <= 3'd0;
                end else begin
                    shift   <= {shift[5:0], mosi_s};
                    bit_cnt <= bit_cnt + 3'd1;
                end
            end
        end
    end

endmodule
