        logic sclk;
        logic mosi;
        logic cs_n;
    } spi_sig_t;

    localparam spi_sig_t SPI_IDLE = '{sclk: 1'b0, mosi: 1'b0, cs_n: 1'b1};

    // 2-stage synchronizer, plus one extra sclk stage for edge detection
    spi_sig_t   sync1, sync2;
    logic       sclk_d;

