    always_ff @(posedge clk) begin
        if (!rst_n) begin
            sync1  <= SPI_IDLE;
            sync2  <= SPI_IDLE;
            sclk_d <= 1'b0;
        end else begin
            sync1  <= '{sclk: sclk, mosi: mosi, cs_n: cs_n};
            sync2  <= sync1;
            sclk_d <= sync2.sclk;
        end
    end

    // Receive logic
    always_ff @(posedge clk) begin
        if (!rst_n) begin                       // E0
            bit_count <= 3'd0;
            data      <= 8'd0;
            valid     <= 1'b0;
            shift_reg <= 7'd0;
        end else if (sync2.cs_n) begin          // E1
            bit_count <= 3'd0;
            valid     <= 1'b0;
        end else if (sclk_rise) begin
            if (bit_count == 3'd7) begin        // E3
                data      <= {shift_reg, sync2.mosi};
                valid     <= 1'b1;
                bit_count <= 3'd0;
            end else begin                      // E2
                shift_reg <= {shift_reg[5:0], sync2.mosi};
                bit_count <= bit_count + 3'd1;
                valid     <= 1'b0;
            end
        end else begin                          // E4
            valid <= 1'b0;
        end
    end

