    output logic       full,     // 1 when 4 items are stored
    output logic       empty     // 1 when 0 items are stored
);

    logic [7:0] mem [0:3];
    logic [1:0] wr_ptr;
    logic [1:0] rd_ptr;
    logic [2:0] count;

    logic wr_ok;
    logic rd_ok;

    assign full   = (count == 3'd4);
    assign empty  = (count == 3'd0);
    assign wr_ok  = wr_en & ~full;
    assign rd_ok  = rd_en & ~empty;

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr  <= 2'd0;
            rd_ptr  <= 2'd0;
            count   <= 3'd0;
            rd_data <= 8'd0;
        end else begin
            if (wr_ok) begin
                mem[wr_ptr] <= wr_data;
                wr_ptr      <= wr_ptr + 2'd1;
            end
            if (rd_ok) begin
                rd_data <= mem[rd_ptr];
                rd_ptr  <= rd_ptr + 2'd1;
            end
            if (wr_ok && !rd_ok)
                count <= count + 3'd1;
            else if (rd_ok && !wr_ok)
                count <= count - 3'd1;
        end
    end

endmodule
```

I implemented this as a 4-entry circular buffer with separate read and write pointers and a count `n` from 0 to 4. `full` and `empty` are registered flags derived from the next count.

Two details of the operation table drive the logic:

- **Write acceptance:** a write is accepted when `wr_en` is set and either the FIFO is not full, or a read is also accepted. The table says the full case with `rd_en=1` and `empty=0` ignores the write, so acceptance is `wr_en && !full`.
- **Read acceptance:** a read is accepted when `rd_en` is set and the FIFO is not empty. When the FIFO is empty and a write arrives together with a read, the read is ignored. The oldest item is read from memory, so no bypass is needed.

The pointers are 2 bits wide and wrap naturally. In the simultaneous read and write case with `n` between 1 and 3, the read returns `mem[rd_ptr]` while the write goes to `mem[wr_ptr]`. These are different locations, because `n` is neither 0 nor 4 there.

