module sync_fifo (
    input  logic       clk,      // clock
    input  logic       rst_n,    // active-low synchronous reset
    input  logic       wr_en,    // write request
    input  logic [7:0] wr_data,  // data to write
    input  logic       rd_en,    // read request
    output logic [7:0] rd_data,  // data of the most recent accepted read (registered)
    output logic       full,     // 1 when 4 items are stored
    output logic       empty     // 1 when 0 items are stored
);

    logic [7:0] mem [0:3];
    logic [1:0] wr_ptr, rd_ptr;
    logic [2:0] count;
    logic       wr_acc, rd_acc;
    logic [2:0] count_next;

    always_comb begin
        wr_acc = wr_en && !full;
        rd_acc = rd_en && !empty;
        count_next = count;
        if (wr_acc && !rd_acc)
            count_next = count + 3'd1;
        else if (!wr_acc && rd_acc)
            count_next = count - 3'd1;
    end

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr  <= 2'd0;
            rd_ptr  <= 2'd0;
            count   <= 3'd0;
            rd_data <= 8'd0;
            full    <= 1'b0;
            empty   <= 1'b1;
        end else begin
            if (wr_acc) begin
                mem[wr_ptr] <= wr_data;
                wr_ptr      <= wr_ptr + 2'd1;
            end
            if (rd_acc) begin
                rd_data <= mem[rd_ptr];
                rd_ptr  <= rd_ptr + 2'd1;
            end
            count <= count_next;
            full  <= (count_next == 3'd4);
            empty <= (count_next == 3'd0);
        end
    end

endmodule
```

Design notes:

- The FIFO uses a 4-entry memory, 2-bit read and write pointers, and a 3-bit count `n`.
- Acceptance is computed from the registered flags: `do_wr = wr_en && !full`, and `do_rd = rd_en && !empty`.
- When full, a simultaneous read and write accepts only the read, because `do_wr` is 0 when full. When empty, a simultaneous read and write accepts only the write, because `do_rd` is 0 when empty.
- On an accepted read, `rd_data` loads `mem[rptr]`.
- When empty, no read is accepted, so no bypass is needed.
- When both are accepted, n is neither empty nor full, so the read pointer never points at the entry being written.
- `full` and `empty` are registered and are updated from the next count `n'`.

```systemverilog
module sync_fifo (
    input  logic       clk,      // clock
    input  logic       rst_n,    // active-low synchronous reset
    input  logic       wr_en,    // write request
