    logic [1:0] wptr, rptr;
    logic [2:0] n;
    logic       do_wr, do_rd;
    logic [2:0] n_next;

    always_comb begin
        do_wr = wr_en && !full;
        do_rd = rd_en && !empty;
        n_next = n;
        if (do_wr && !do_rd) n_next = n + 3'd1;
        else if (do_rd && !do_wr) n_next = n - 3'd1;
    end

