                mem[wptr] <= wr_data;
                wptr      <= wptr + 2'd1;
            end
            if (do_rd) begin
                rd_data <= mem[rptr];
                rptr    <= rptr + 2'd1;
            end
            n     <= n_next;
            empty <= (n_next == 3'd0);
            full  <= (n_next == 3'd4);
        end
    end

endmodule
