Design notes:

- The three async inputs each go through a 2-stage synchronizer.
- Rising-edge detection on sclk compares the synchronized sclk with a one-cycle-delayed copy of it.
- mosi is sampled at the same time as the edge is detected. Since mosi and sclk pass through identical synchronizer delays, they stay aligned.
- The spec says "a byte boundary is re-aligned every time cs_n falls". E1 already clears bit_count whenever cs_n = 1, so the count is 0 when cs_n falls.
- The sclk delay register is updated every cycle, including during reset. This avoids a false edge right after reset or while cs_n is high.
- valid defaults to 0 each cycle and is set only in E3, which gives a one-cycle pulse.
- shift_reg is not cleared by reset, because the spec says reset clears data, valid, and bit count. Clearing it as well is harmless, so I clear it for cleanliness.
- The synchronizer registers are not reset, which is the usual practice. They flush within 2 cycles.
- bit_count is 3 bits wide, counting 0 to 7.

```verilog
module spi_slave_rx (
    input  wire       clk,    // system clock
    input  wire       rst_n,  // active-low synchronous reset
    input  wire       sclk,   // SPI clock from master (asynchronous to clk)
    input  wire       mosi,   // master-out slave-in data
    input  wire       cs_n,   // active-low chip select
    output reg  [7:0] data,   // last complete byte received
    output reg        valid   // one-clk-cycle pulse when data is updated
);

    reg [1:0] sclk_sync;
    reg [1:0] mosi_sync;
    reg [1:0] cs_sync;
    reg       sclk_prev;
    reg [7:0] shift_reg;
    reg [2:0] bit_count;

    wire sclk_s = sclk_sync[1];
    wire mosi_s = mosi_sync[1];
    wire cs_s   = cs_sync[1];
    wire sclk_rise = sclk_s & ~sclk_prev;

    always @(posedge clk) begin
        sclk_sync <= {sclk_sync[0], sclk};
        mosi_sync <= {mosi_sync[0], mosi};
        cs_sync   <= {cs_sync[0], cs_n};
        sclk_prev <= sclk_s;
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            bit_count <= 3'd0;
            data      <= 8'd0;
            valid     <= 1'b0;
            shift_reg <= 8'd0;
        end else begin
            valid <= 1'b0;
            if (cs_s) begin
                bit_count <= 3'd0;
            end else if (sclk_rise) begin
                if (bit_count == 3'd7) begin
                    data      <= {shift_reg[6:0], mosi_s};
                    valid     <= 1'b1;
                    bit_count <= 3'd0;
                end else begin
                    shift_reg <= {shift_reg[6:0], mosi_s};
                    bit_count <= bit_count + 3'd1;
                end
            end
        end
    end

endmodule
