    reg [1:0] wr_ptr;
    reg [1:0] rd_ptr;
    reg [2:0] count;

    // Write accepted when requested and not full; read accepted when requested and not empty.
    wire wr_acc = wr_en & ~full;
    wire rd_acc = rd_en & ~empty;

    wire [2:0] count_nxt = count + {2'b00, wr_acc} - {2'b00, rd_acc};

