    output reg  [7:0] rd_data,  // data of the most recent accepted read (registered)
    output reg        full,     // 1 when 4 items are stored
    output reg        empty     // 1 when 0 items are stored
);

    reg [7:0] mem [0:3];
    reg [1:0] rd_ptr;
    reg [1:0] wr_ptr;
    reg [2:0] n;

    wire wr_acc = wr_en && !full;
    wire rd_acc = rd_en && !empty;

    reg [2:0] n_next;

    always @(*) begin
        n_next = n;
        if (wr_acc && !rd_acc)
            n_next = n + 3'd1;
        else if (!wr_acc && rd_acc)
            n_next = n - 3'd1;
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            n       <= 3'd0;
            rd_ptr  <= 2'd0;
            wr_ptr  <= 2'd0;
            rd_data <= 8'd0;
            empty   <= 1'b1;
            full    <= 1'b0;
        end else begin
            if (wr_acc) begin
                mem[wr_ptr] <= wr_data;
                wr_ptr      <= wr_ptr + 2'd1;
            end
            if (rd_acc) begin
                rd_data <= mem[rd_ptr];
                rd_ptr  <= rd_ptr + 2'd1;
            end
            n     <= n_next;
            empty <= (n_next == 3'd0);
            full  <= (n_next == 3'd4);
        end
    end

endmodule
```

Design notes:

- Storage is four 8-bit entries with 2-bit read and write pointers and a 3-bit count `n`.
- Write acceptance is `wr_en && !full`, except when full with a simultaneous read. The table says write is ignored when `full=1`, so `wr_ok = wr_en && !full`.
- Read acceptance is `rd_en && !empty`.
- With a simultaneous read and write while neither full nor empty, both are accepted and `n` is unchanged.
- With full and both requested, only the read is accepted, so `n` decreases.
- With empty and both requested, only the write is accepted, so `n` increases.
- The read data is `mem[rd_ptr]`. Reading and writing in the same cycle never touches the same entry unless `n=0`, and then no read is accepted, so there is no hazard.
- `full` and `empty` are registered from `n'`.

