    input  wire       wr_en,    // write request
    input  wire [7:0] wr_data,  // data to write
    input  wire       rd_en,    // read request
    output reg  [7:0] rd_data,  // data of the most recent accepted read (registered)
    output reg        full,     // 1 when 4 items are stored
    output reg        empty     // 1 when 0 items are stored
);

    reg [7:0] mem0, mem1, mem2, mem3;
    reg [1:0] wr_ptr;
    reg [1:0] rd_ptr;
    reg [2:0] count;

    wire wr_acc = wr_en & ~full;
    wire rd_acc = rd_en & ~empty;

    reg [2:0] count_next;
    reg [7:0] rd_sel;

    always @(*) begin
        count_next = count;
        if (wr_acc & ~rd_acc)
            count_next = count + 3'd1;
        else if (rd_acc & ~wr_acc)
            count_next = count - 3'd1;
    end

    always @(*) begin
        case (rd_ptr)
            2'd0: rd_sel = mem0;
            2'd1: rd_sel = mem1;
            2'd2: rd_sel = mem2;
            default: rd_sel = mem3;
        endcase
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr  <= 2'd0;
            rd_ptr  <= 2'd0;
            count   <= 3'd0;
            rd_data <= 8'd0;
            full    <= 1'b0;
            empty   <= 1'b1;
            mem0    <= 8'd0;
            mem1    <= 8'd0;
            mem2    <= 8'd0;
            mem3    <= 8'd0;
        end else begin
            if (wr_acc) begin
                case (wr_ptr)
                    2'd0: mem0 <= wr_data;
                    2'd1: mem1 <= wr_data;
                    2'd2: mem2 <= wr_data;
                    default: mem3 <= wr_data;
                endcase
                wr_ptr <= wr_ptr + 2'd1;
            end
            if (rd_acc) begin
                rd_data <= rd_sel;
                rd_ptr  <= rd_ptr + 2'd1;
            end
            count <= count_next;
            full  <= (count_next == 3'd4);
            empty <= (count_next == 3'd0);
        end
    end

endmodule
